enum LoadState {
  Idle
  Loading
  Ready(String)
}
fn main {
  let state : LoadState = Ready("done")
  ignore(state)
}

fn message(state : LoadState) -> String {
  match state {
    Idle => "waiting"
    Loading => "loading"
    Ready(text) => text
  }
}
fn main { println(message(Ready("done"))) }

fn or_zero(value : Int?) -> Int {
  match value {
    Some(n) => n
    None => 0
  }
}
fn main { println(or_zero(None)) }

