fn accept(n : Int) -> Result[Int, String] {
  if n >= 0 { Ok(n) } else { Err("negative") }
}
fn main {
  match accept(-1) {
    Ok(n) => println(n)
    Err(reason) => println(reason)
  }
}

suberror Negative
fn checked(n : Int) -> Int raise Negative {
  if n < 0 { raise Negative }
  n
}

fn main {
  let value = try checked(-2) catch {
    Negative => 0
  }
  println(value) // 0
}

test "addition and fallback" {
  assert_eq(add(6, 7), 13)
  assert_eq(or_zero(None), 0)
  assert_eq(or_zero(Some(9)), 9)
}
